module sync_fifo #(
  parameter  int DW    = 8,
  parameter  int DEPTH = 16,               // a power of two
  localparam int AW    = $clog2(DEPTH)
) (
  input  logic          clk, rst_n,
  input  logic          wr_en,             // push
  input  logic [DW-1:0] din,
  output logic          full,
  input  logic          rd_en,             // pop
  output logic [DW-1:0] dout,              // valid one clock after a pop
  output logic          empty
);
  logic [DW-1:0] mem [DEPTH];
  logic [AW:0]   wptr, rptr;               // one extra bit = wrap flag
  logic          do_wr, do_rd;

  assign do_wr = wr_en && !full;           // ignore a push when full
  assign do_rd = rd_en && !empty;          // ignore a pop when empty

  always_ff @(posedge clk or negedge rst_n)
    if (!rst_n) begin
      wptr <= '0;
      rptr <= '0;
    end else begin
      if (do_wr) wptr <= wptr + 1'b1;
      if (do_rd) rptr <= rptr + 1'b1;
    end

  always_ff @(posedge clk) begin
    if (do_wr) mem[wptr[AW-1:0]] <= din;
    if (do_rd) dout <= mem[rptr[AW-1:0]];
  end

  // equal pointers: empty; equal addresses but different wrap bits: full
  assign empty = (wptr == rptr);
  assign full  = (wptr[AW-1:0] == rptr[AW-1:0]) && (wptr[AW] != rptr[AW]);
endmodule
